import posthog

posthog.api_key = os.getenv('POSTHOG_API_KEY')
posthog.host = os.getenv('POSTHOG_HOST', 'https://app.posthog.com')
posthog.disabled = os.getenv('ENVIRONMENT', 'development') == 'development'  # skip in dev

def capture_event(distinct_id: str, event: str, properties: dict | None = None) -> None:
    posthog.capture(distinct_id, event, properties or {})

def identify_user(distinct_id: str, properties: dict | None = None) -> None:
    posthog.identify(distinct_id, properties or {})

def is_feature_enabled(flag_key: str, distinct_id: str) -> bool:
    return posthog.feature_enabled(flag_key, distinct_id) or False

def get_feature_flag_payload(flag_key: str, distinct_id: str):
    return posthog.get_feature_flag_payload(flag_key, distinct_id)

