const { PostHog } = require('posthog-node');

const ph = new PostHog(process.env.POSTHOG_API_KEY, {
  host: process.env.POSTHOG_HOST || 'https://app.posthog.com',
  disabled: process.env.NODE_ENV === 'development',
});

const captureEvent = (distinctId, event, properties = {}) =>
  ph.capture({ distinctId, event, properties });

const identifyUser = (distinctId, properties = {}) =>
  ph.identify({ distinctId, properties });

const isFeatureEnabled = async (flagKey, distinctId) =>
  ph.isFeatureEnabled(flagKey, distinctId);

process.on('exit', () => ph.shutdown());
